  [200597] = { n="The Sporelord's Gift", d="While in combat, you periodically summon Spores for 20 sec, increasing the critical strike damage of nearby allies by 10%.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Healer", "Melee DPS", "Ranged DPS"}, t=true },
