  [200601] = { n="The Harvester’s Tithe", d="You constantly harvest the souls of nearby enemies, gaining a stack of Harvested Soul. Each stack increases your damage done by 1%. Up to 10% increase.\n\nWhen an enemy with its soul harvested dies, you regain 10+\nH*0.5+attack power*0.25 health.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200606] = { n="Edict of the Four", d="Your damaging spells and abilities build Edict. At 10 stacks, you invoke an Edict, cycling through the following effects in order: Meteor, Void Zone, Unholy Shadow and Holy Wrath. Each invocation triggers its effect at your target’s location.\n\nMeteor : Deals 50+fire spell powerI*2.5+attack power*1.25 Fire damage, split between all enemies within 8 yds of the impact.\n\nVoid Zone : Summons a Void Zone for -0.0 sec sec that deals 10+shadow spell power*0.5+attack power*0.25 Shadow damage every 1 sec to enemies within it.\n\nUnholy Shadow : Deals 15+shadow spell power*1+attack power*0.5 Shadow damage, plus 5+shadow spell power*0.25+attack power*0.125 Shadow damage every 1 sec for 8 sec.\n\nHoly Wrath : Hurls Holy bolts that deal 10+holy spell power*0.75+attack power*0.375 Holy damage to the target, jumping to additional nearby enemies. Damage increases by 50% with each jump.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200613] = { n="Stitched Fury", d="While below 15% health, you go into a Frenzy, increasing Attack Speed by 30% and Physical damage dealt by 25%.", cm=1535, q=3, lvl=1, ms=1, f={"Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200615] = { n="Mutagenic Fumes", d="Killing an enemy summons a Poison Cloud for 20, dealing 5+nature spell power*0.2+attack power*0.1 Nature damage to nearby enemies every 1. \n\nThis effect cannot occur more than once every 8 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200619] = { n="Ravenous Bellow", d="Delivering a killing blow unleashes Terrifying Roar, dealing 10+shadow spell power*0.3+attack power*0.15 damage to enemies within 10 yds, slowing them by 50% and causing them to take 15% increased damage from you for 5 sec.\n\nThis effect cannot occur more than once every 2 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Melee DPS", "Tank"}, t=true },
  [200621] = { n="Polarity Shift", d="You alternate between Positive Charge and Negative Charge.\nTaking direct melee damage shifts you to Negative Charge.\nWhile under Negative Charge, going 1 sec without taking direct melee damage shifts you to Positive Charge.\n\nYou cannot shift more than once every 4 sec.\n\nPositive Charge: Increases your critical strike chance by 10% and damage dealt by 5%.\n\nNegative Charge: Reduces damage taken by 10%, increases healing received by 5%, and increases your movement speed by 5%.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200627] = { n="Chill of the Bone Wyrm", d="Dealing Frost damage grants a stack of Rime. At 12 stacks, you unleash Frost Breath in front of you, dealing 30+frost spell power*1.75+attack power*0.875 Frost damage and leaving enemies hit Brittle for 5 sec.\n\nWhile Brittle is active, your Frost damage against them is increased by 10%. \n\nAfter triggering, you cannot gain Rime stacks for 4 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS"}, t=true },
  [200632] = { n="Call of the Lich King", d="Killing an enemy grants a Soul Fragment. At 6 Soul Fragments, they are consumed to summon a Servant of the Lich King for 30 sec.\n\nYou can have up to 6 Servants active at once.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [200635] = { n="Cinders of the Sanctum", d="Dealing Fire damage grants a stack of Cinders. At 12 stacks, you summon a Fire Cyclone for 12 sec., dealing 10+fire spell powerI*0.3+attack power*0.15 Fire damage to enemies within 10 yds every 2 sec. \n\nAfter triggering, you cannot gain Cinders stacks for 4 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS"}, t=true },
  [200639] = { n="Storm of the Spellweaver", d="Dealing Arcane damage grants a stack of Overcharge. At 10 stacks, you fire a salvo of Magic Missiles into the air, striking up to 3 enemies near the target for 20+arcane spell power*1.5+attack power*0.75 Arcane damage each.\n\nAfter triggering, you cannot gain Overcharge stacks for 2 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS"}, t=true },
  [200661] = { n="Spiteful Shard", d="Taking direct damage has a chance to cause a Glacial Spike to erupt beneath the attacker, dealing 5% of spell power or 2.5% of attack power Frost damage and knocking them into the air. \n\nThis effect deals at least 15 damage.", cm=1535, q=0, lvl=1, ms=80, f={"Tank"}, t=false },
  [200662] = { n="Spiteful Shard", d="Taking direct damage has a chance to cause a Glacial Spike to erupt beneath the attacker, dealing 10% of spell power or 5% of attack power Frost damage and knocking them into the air. \n\nThis effect deals at least 15 damage.", cm=1535, q=1, lvl=1, ms=80, f={"Tank"}, t=false },
  [200663] = { n="Spiteful Shard", d="Taking direct damage has a chance to cause a Glacial Spike to erupt beneath the attacker, dealing 50% of spell power or 25% of attack power Frost damage and knocking them into the air. \n\nThis effect deals at least 15 damage.", cm=1535, q=2, lvl=1, ms=80, f={"Tank"}, t=false },
  [200665] = { n="Scorched Path", d="While in combat, moving leaves a trail of embers behind you for 3 sec, burning enemies who pass through it for 2% of spell power or 1% of attack power Fire damage and slowing them by 30%. \n\nThis effect deals at least 8 damage.", cm=1535, q=0, lvl=1, ms=80, f={"Caster DPS", "Melee DPS", "Tank"}, t=false },
  [200666] = { n="Scorched Path", d="While in combat, moving leaves a trail of embers behind you for 3 sec, burning enemies who pass through it for 4% of spell power or 2% of attack power Fire damage and slowing them by 30%. \n\nThis effect deals at least 8 damage.", cm=1535, q=1, lvl=1, ms=80, f={"Caster DPS", "Melee DPS", "Tank"}, t=false },
  [200667] = { n="Scorched Path", d="While in combat, moving leaves a trail of embers behind you for 3 sec, burning enemies who pass through it for 20% of spell power or 10% of attack power Fire damage and slowing them by 30%. \n\nThis effect deals at least 8 damage.", cm=1535, q=2, lvl=1, ms=80, f={"Caster DPS", "Melee DPS", "Tank"}, t=false },
