  [200776] = { n="Flame Vents", d="Dodging or Parrying builds Pressure, maximum 1 stack every 0,3 seconds. At 12 stacks, you vent flames for 8 sec, dealing 5 plus 80% of Stamina Fire damage every 1 sec to enemies within 0 yards, scaling with your Stamina.\n\nWhile Flame Vents is active, you take 15% reduced damage and your movement speed is increased by an additional 20%.", cm=1535, q=3, lvl=1, ms=1, f={"Tank"}, t=true },
  [200780] = { n="Brittle Forging", d="Your Fire damage builds Heat on the target. At 10 stacks, the target becomes Brittle for 6 sec, increasing your critical strike chance against it by 20%. \n\nWhile Brittle is active, your next Fire critical strike against the target causes it to Shatter, dealing 20 plus 100% of spell power or 50% of attack power Fire damage to enemies within 8 yards. \n\nOnce Brittle expires, the target cannot gain Heat stacks for 6 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [200786] = { n="Harpoon Barrage", d="Every 8 sec while in combat, you throw Harpoons at up to 5 enemies between 8 and 35 yards away, pulling them to you and Pinning them for 5 sec.\n\nPinned enemies are slowed by 50% and take 15% increased damage from you.", cm=1535, q=3, lvl=1, ms=1, f={"Tank"}, t=true },
  [200792] = { n="Exposed Heart", d="Your basic attacks builds Stress. At 12 stacks, you expose your target’s heart for 6 sec, increasing your damage dealt to it by 20%. \n\nWhile Exposed Heart is active, 40% of the damage you deal to the target is also dealt to all enemies within 8 yards of it. While Exposed Heart is active and up to 6 seconds after it expires you cannot generate Stress on any target.", cm=1535, q=3, lvl=1, ms=1, f={"Melee DPS", "Ranged DPS"}, t=true },
  [200798] = { n="Edict of the Iron Council", d="Your damaging spells and abilities build Edict. At 10 stacks, you invoke an Edict, cycling through the following effects in order: Rune of Death, Overload, Fusion Punch.\n\nRune of Death : Summons a Rune of Death under your target for 8 sec, dealing 5 plus 25% of spell power or 12.5% of attack power Shadow damage every half-second to enemies within 13 yards.\n\nOverload : You erupt with lightning, dealing 35 plus 175% of spell power or 87.5% of attack power Nature damage to enemies within 10 yards.\n\nFusion Punch : Your next melee attack deals an additional 50 plus 250% of spell power or 125% of attack power Nature damage and an additional 25 plus 125% of spell power or 62.5% of attack power Nature damage every 1 sec for 6 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [200804] = { n="Stone Shatter", d="The first time you damage an enemy, you mark it with Fracture for 10 sec. \n\nIf it dies while fractured, it shatters, dealing 10 plus 50% of spell power or 25% of attack power Physical damage to enemies within 8 yards.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [200808] = { n="Sanctum Sentries", d="While in combat you are accompanied by two Sanctum Sentries.\n\nEnemies struck by either guardian take 10% increased damage from you for 4 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200818] = { n="Eonar’s Seed", d="Up to 20% of your overhealing on allies is stored as Eonar’s Seed for 10 sec. \n\nWhen the target health lowers under 50%, it blooms, healing the target aswell as the most injured nearby ally for the stored amount. Stored amount cannot exceed 40% of the target's maximum health.", cm=1535, q=3, lvl=1, ms=1, f={"Healer"}, t=true },
  [200822] = { n="Frostfire Paradox", d="Your Frost damage applies Biting Cold for 6 sec, stacking up to 10 times. \n\nYour direct Fire damage against a target with 6 or more stacks Shatters it, consuming all stacks and dealing 3 plus 15% of spell power or 7.5% of attack power Frost damage per stack to the target and to enemies within 8 yards.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS"}, t=true },
  [200826] = { n="Rocket Strike", d="Your melee and ranged attacks have a 5% chance to launch a Rocket at your target, dealing 15 plus 75% of spell power or 37.5% of attack power Fire damage. \n\nYou fire 1 additional Rocket on random nearby enemies for each of your active pets or guardians. Subsequent Rockets hitting the same target deal reduced damage.", cm=1535, q=3, lvl=1, ms=1, f={"Melee DPS", "Ranged DPS"}, t=true },
  [200830] = { n="Lightning Charged", d="While in combat, you gain Lightning Charged every 8 sec, stacking up to 5 times lasting 12 sec.\n\nEach stack increases your attack speed by 2% and causes your melee and ranged auto-attacks to deal an additional 1 plus 5% of attack power Nature damage.\n\nAt 5 stacks, your auto-attacks instead unleash Chain Lightning at the target, dealing 5 plus 25% of attack power Nature damage and chaining up to 5 times. Effect is lost on exiting combat.", cm=1535, q=3, lvl=1, ms=1, f={"Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200834] = { n="Shadow Crash", d="Your Shadow damage-over-time damage have a 3% chance to hurl a Shadow Crash at the target. \n\nOn impact, it deals 20 plus 100% of spell power or 50% of attack power Shadow damage to enemies within 10 yards", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS"}, t=true },
  [200838] = { n="Idol of Yogg-Saron", d="Whenever you kill an enemy, gain a stack of Idol of Yogg-Saron. At 10 stacks, you summon a Thing from Beyond that casts Void Spike at nearby enemies for 20 sec. \n\nVoid Spike : Hurls a bolt of dark magic, dealing 15 plus 75% of spell power or 37.5% of attack power Shadow damage and 5 plus 20% of spell power or 10% of attack power Shadow damage to all enemies within 10 yards of the target.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200844] = { n="Constellations", d="Your critical strikes have a 10% chance to summon a Falling Star that strikes a nearby enemy for 10 plus 50% of spell power or 25% of attack power Arcane damage. \n\nAfter 5 Falling Stars strike, you trigger Big Bang, dealing 100 plus 500% of spell power or 250% of attack power Arcane damage split between all enemies within 12 yards of your target.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [200850] = { n="Earthen Spike", d="When struck by a melee attack, you have a chance to launch an earthen spike at the attacker, dealing 20 plus 15% of armor damage to the attacker and nearby enemies.\n\nDamage is further increased by your Armor and generates a high amount of threat.", cm=1535, q=2, lvl=1, ms=80, f={"Tank"}, t=true },
  [200852] = { n="Emberlord’s Gift", d="Dealing Fire damage grants a stack of Kindling. \n\nAt 100 stacks, you erupt in flame, dealing 90 plus 300% of spell power or 150% of attack power Fire damage to nearby enemies and 90 plus 300% of spell power or 150% of attack power additional Fire damage over time for 6 sec.\n\nAfter erupting, you cannot gain Kindling for 6 sec.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS", "Melee DPS"}, t=true },
  [200856] = { n="Mana Infusion", d="While above 80% mana, restoring mana also restores health equal to 50% of the mana restored.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS", "Healer"}, t=true },
  [200858] = { n="Permafrost Aura ", d="While in combat, you deal 16% of spell power or 8% of attack power Frost damage every 2 sec to enemies within 8 yards.\n\nThis effect deals at least 5 damage.\n\nEnemies hit have their attack speed reduced by 5% for 3 sec.", cm=1535, q=2, lvl=1, ms=80, f={"Melee DPS", "Tank"}, t=true },
  [200860] = { n="Static Overflow", d="Every 3 sec while in combat, your next spell or ability also hurls lightning at up to 3 random nearby enemies, dealing 40% of spell power or 20% of attack power Nature damage.\n\nThis effect deals at least 15 damage.", cm=1535, q=2, lvl=1, ms=80, f={"Caster DPS", "Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200864] = { n="Unstable Missiles", d="Your direct spells have a chance to launch an Unstable Missile at the target, dealing 30% of spell power or 15% of attack power Arcane damage.\n\nThis effect deals at least 10 damage.", cm=1535, q=2, lvl=1, ms=80, f={"Caster DPS"}, t=true },
  [200866] = { n="Hungering Curse", d="Every 2 sec while in combat, you afflict a nearby enemy with Siphon Life, dealing 120% of spell power or 60% of attack power Shadow damage over 12 sec. \n\nIf the affected target dies, you are healed for 20% of spell power or 10% of attack power.\n\nThis effect deals at least 5 damage and heals at least 10 health.", cm=1535, q=2, lvl=1, ms=80, f={"Caster DPS", "Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200870] = { n="Relentless Energy", d="While below 80% Energy, your Energy regeneration is increased by 10%. \nWhile above 80% Energy, your damage done is increased by 10%.", cm=1535, q=2, lvl=1, ms=1, f={"Melee DPS"}, t=true },
  [200874] = { n="Raging Momentum", d="While below 80% Rage, your Rage generation is increased by 20%. \nWhile above 80% Rage, your damage done is increased by 10%.", cm=1535, q=2, lvl=1, ms=1, f={"Melee DPS", "Tank"}, t=true },
  [200878] = { n="Runic Momentum", d="While below 80% Runic Power, your Runic Power generation is increased by 20%. \nWhile above 80% Runic Power, your damage done is increased by 10%.", cm=1535, q=2, lvl=1, ms=1, f={"Melee DPS", "Tank"}, t=true },
  [200882] = { n="Arcane Density", d="Increases your Spell Power by an amount equal to 5% of your Armor, up to a maximum of 150% of your intellect.\n\nCurrent bonus: Spell Power.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS", "Healer"}, t=true },
  [200884] = { n="Fortress Soul", d="Reduces damage taken by 35%, but reduces damage dealt by 70%. Increases threat generated by 200%.", cm=1535, q=2, lvl=1, ms=1, f={"Tank"}, t=true },
  [200886] = { n="The Last Wall", d="Increases your maximum health by 50%, but reduces healing received by 60%.", cm=1535, q=2, lvl=1, ms=1, f={"Tank"}, t=true },
  [200888] = { n="Arcane Burn", d="While above 20% mana, your spell damage done is increased by 15%, but your ressource costs are increased by 50%.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS"}, t=true },
  [200890] = { n="Crushing Finish", d="When you damage a target below 30% health with a melee or ranged attack, you Execute it, dealing 10 plus 50% of attack power Physical damage. Damage is increased by 2% per point of Expertise.\n\nCannot occur more than once every 6 sec per target.", cm=1535, q=2, lvl=1, ms=1, f={"Melee DPS", "Ranged DPS"}, t=true },
  [200894] = { n="Archmage’s Mark", d="Dealing Fire, Frost, and Arcane damage within 6 sec increases the damage you deal by 10% for 12 sec.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [200896] = { n="Entropic Fusion", d="Dealing Fire and Shadow damage within 3 sec increases the damage you deal by 10% for 6 sec.", cm=1535, q=2, lvl=10, ms=1, f={"Caster DPS", "Ranged DPS"}, t=true },
  [200898] = { n="Battle Rhythm", d="Increases your critical strike damage by 1%, plus an additional 1% for every 150 Critical Strike Rating you have.\n\nCurrent bonus: 1 plus 0.66% of critical strike rating%", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [200900] = { n="Arcane Cadence", d="Casting an offensive spell or ability increases your damage done by 3% for 6 sec. \n\nWhile this effect is active, each different offensive spell or ability you use increases this bonus by an additional 3% and refreshes the duration.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [200902] = { n="Healing Cadence", d="Casting a healing spell or ability increases your healing done by 3% for 6 sec. \n\nWhile this effect is active, each different healing spell or ability you use increases this bonus by an additional 3% and refreshes the duration.", cm=1535, q=2, lvl=1, ms=1, f={"Healer"}, t=true },
  [200904] = { n="Battlefield Hazard", d="While 4 or more enemies are within range, the damage of your Thunder Clap, Shockwave, Whirlwind, and Bladestorm is increased by 20%.", cm=1535, q=2, lvl=1, ms=1, f={"Melee DPS", "Tank"}, t=true },
  [200908] = { n="Sanctified Hazard", d="While 4 or more enemies are within range, the damage of your Consecration, Divine Storm, and Hammer of the Righteous is increased by 20%.", cm=1535, q=2, lvl=1, ms=1, f={"Melee DPS", "Tank"}, t=true },
  [200912] = { n="Blighted Hazard", d="While 4 or more enemies are within range, the damage of your Death and Decay, Blood Boil, Howling Blast, and Corpse Explosion is increased by 20%.", cm=1535, q=2, lvl=1, ms=1, f={"Melee DPS", "Tank"}, t=true },
  [200916] = { n="Hunting Hazard", d="While 4 or more enemies are within range, the damage of your Volley and Multi-Shot is increased by 20%.", cm=1535, q=2, lvl=1, ms=1, f={"Ranged DPS"}, t=true },
  [200920] = { n="Storm Hazard", d="While 4 or more enemies are within range, the damage of your Chain Lightning and Thunderstorm is increased by 20%.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS", "Melee DPS"}, t=true },
  [200924] = { n="Wild Hazard", d="While 4 or more enemies are within range, the damage of your Hurricane, Starfall, and Swipe is increased by 20%.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS", "Melee DPS"}, t=true },
  [200928] = { n="Shadow Hazard", d="While 4 or more enemies are within range, the damage of your Fan of Knives is increased by 20%.", cm=1535, q=2, lvl=1, ms=1, f={"Melee DPS"}, t=true },
  [200932] = { n="Arcane Hazard", d="While 4 or more enemies are within range, the damage of your Arcane Explosion, Blizzard, Flamestrike, and Blast Wave is increased by 20%.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS"}, t=true },
  [200936] = { n="Holy Hazard", d="While 4 or more enemies are within range, the damage of your Holy Nova is increased by 20%.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS"}, t=true },
  [200940] = { n="Fel Hazard", d="While 4 or more enemies are within range, the damage of your Rain of Fire, Hellfire, Shadowflame, and Shadowfury is increased by 20%.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS"}, t=true },
  [200944] = { n="Crusader's Surge", d="Casting a spell or ability has a chance to make your next eligible spell instant-cast. \n\nEligible spells : Exorcism, Flash of Light, Holy Light.", cm=1535, q=2, lvl=1, ms=1, f={"Healer"}, t=true },
  [200946] = { n="Divine Surge", d="Casting a spell or ability has a chance to make your next eligible spell instant-cast. \n\nEligible spells: Smite, Holy Fire, Mind Blast, Flash Heal, Greater Heal, Heal, Binding Heal, and Prayer of Healing.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS", "Healer"}, t=true },
  [200948] = { n="Storm Surge", d="Casting a spell or ability has a chance to make your next eligible spell instant-cast. \n\nEligible spells: Lightning Bolt, Chain Lightning, Lava Burst, Healing Wave, Chain Heal.", cm=64, q=2, lvl=1, ms=1, f={"Caster DPS", "Healer"}, t=true },
  [200950] = { n="Arcane Surge", d="Casting a spell or ability has a chance to make your next eligible spell instant-cast. \n\nEligible spells: Arcane Blast, Fireball, Frostbolt, Frostfire Bolt, Pyroblast, Flamestrike.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS"}, t=true },
  [200952] = { n="Fel Surge", d="Casting a spell or ability has a chance to make your next eligible spell instant-cast. \n\nEligible spells: Shadow Bolt, Incinerate, Soul Fire, Chaos Bolt, Seed of Corruption, Haunt, Unstable Affliction.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS"}, t=true },
  [200954] = { n="Nature’s Surge", d="Casting a spell or ability has a chance to make your next eligible spell instant-cast. \n\nEligible spells: Wrath, Starfire. Healing: Healing Touch, Nourish, Regrowth.", cm=1535, q=2, lvl=1, ms=1, f={"Caster DPS", "Healer"}, t=true },
  [200956] = { n="Heavy Incantations", d="Increases the damage of spells with a base cast time longer than 2.5 seconds by 30%.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS"}, t=true },
  [200958] = { n="Weapon Mastery", d="You can equip all weapon types.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [200960] = { n="Adaptive Power", d="Increases your damage by 1% for each unique Echo you have active. \n\nAdditional ranks or qualities of the same Echo do not increase this bonus.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200962] = { n="Resonant Build", d="While you have at least 3 different Base Stat Echo types active (Strength, Agility, Intellect, Spirit, or Stamina), your damage is increased by 15%.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS", "Tank"}, t=true },
  [200964] = { n="Ember Spark", d="For every 60 Rage you spend, a tiny ember leaps from you, dealing 4% of spell power or 2% of attack power Fire damage to a random enemy within 20 yards. \n\nThis effect deals at least 15 damage and cannot occur more than once every 1.5 sec.", cm=1, q=0, lvl=1, ms=80, f={"Melee DPS", "Tank"}, t=false },
