  [201278] = { n="Temporal Pressure", d="Your cooldowns are now reduced by your Haste. Affected spells : Shield Slam, Revenge, Thunder Clap, Mortal Strike, Bloodthirst, Whirlwind, Shockwave, Concussion Blow.", cm=1, q=3, lvl=1, ms=1, f={}, t=true },
