  [201298] = { n="Quickened Tempo", d="Your global cooldown is now reduced by your Haste.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201300] = { n="Impaler’s Tribute", d="Your damaging abilities build Impale on the target. At 8 stacks, you Skewer the target for 8 sec, dealing 5+shadow spell power*0.3+attack power*0.15 Physical damage every 1 sec. \n\nWhile Skewered is active, your attacks against the target have a 20% chance to splinter, dealing 25+shadow spell power*0.4+attack power*0.2 Physical damage to up to 5 nearby enemies.", cm=1535, q=3, lvl=1, ms=1, f={"Melee DPS", "Ranged DPS"}, t=true },
  [201304] = { n="Slimebound Husk", d="Taking direct damage grants a stack of Molten Blood, up to 8. \n\nAt 8 stacks, you shed your skin, leaving behind a Poisonous Slime for 10 sec that deals 10+nature spell power*0.5+attack power*0.25 Nature damage every 1 sec to nearby enemies, while you gain 15% increased movement speed and 10% reduced damage taken for 6 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Survivability", "Tank"}, t=true },
  [201308] = { n="Rage of the Colossus", d="Your critical strikes grant Momentum for 8 sec, stacking up to 10 times. \nMomentum cannot be gained more than once per second. \n\nEach stack increases your movement speed by 2% and damage dealt by 1%. \n\nAt 10 stacks, you unleash a Massive Crash, dealing 50+shadow spell power*2.5+attack power*1.25 Physical damage to enemies within 10 yards of your target.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [201312] = { n="Nether Lord’s Command", d="Your damaging spells and abilities have a chance to open a Nether Portal for 10 sec. \n\nWhile active, the portal hurls Fel Lightning at your target every 2 sec, dealing 25+fire spell powerI*1.25+attack power*0.625 Fel damage. Each strike has a 25% chance to summon a Fel Flamestrike under the target, dealing 40+fire spell powerI*2+attack power*1 Fel damage and burning the ground for 4 sec, dealing 10+fire spell powerI*0.4+attack power*0.2 Fel damage every 1 sec.\n\nYou cannot summon a Nether Portal more than once every 6 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [201318] = { n="Champion’s Rally", d="Your direct healing spells grant Rally for 8 sec. \n\nAt 10 stacks, you unleash Champion’s Rally, instantly healing your target for 40+\nH*2 and granting them Rallying Cry for 6 sec, reducing damage taken by 15% and increasing healing received by 20%. \n\nWhile Rallying Cry is active, 30% of your direct healing on that target is also granted to the most injured nearby ally.", cm=1535, q=3, lvl=1, ms=1, f={"Healer"}, t=true },
  [201324] = { n="Twilight Equilibrium", d="You begin combat in Light Essence.\n\nLight Essence: Dealing Holy, Fire, or Nature damage applies Light Charge for 8 sec, stacking up to 20 times. Dealing Shadow, Frost, or Arcane damage consumes Light Charge to unleash Darkburst, dealing shadow spell power*0.15+attack power*0.075 Shadow damage per stack to the target and all enemies within 8 yards and shifts you into Dark Essence.\n\nDark Essence: Dealing Shadow, Frost, or Arcane damage applies Dark Charge for 8 sec, stacking up to 20 times. Dealing Holy, Fire, or Nature damage consumes Dark Charge to unleash Lightburst, dealing holy spell power*0.15+attack power*0.075 Holy damage per stack to the target and all enemies within 8 yards and shifts you into Light Essence.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [201332] = { n="Leeching Swarm", d="While below 50% health, your damaging spells and abilities unleash Leeching Swarm, dealing nature spell power*0.3+attack power*0.15 Nature damage every 1 sec to all enemies within 10 yds for 6 sec. You are healed for 30% of the damage dealt.\n\nIf Leeching Swarm hits only 1 target, its damage and healing are increased by 100%. Leeching Swarm cannot occur more than once every 6 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Survivability"}, t=true },
  [201336] = { n="Broodmother’s Fury", d="Your direct damage spells and abilities have a chance to apply Searing Cinders for 8 sec, dealing 5+fire spell powerI*0.15+attack power*0.075 Fire damage every 1 sec.\n\nWhen Searing Cinders reaches 5 stacks, it triggers Deep Breath, burning all enemies in a line in front of you for 50+fire spell powerI*2+attack power*1 Fire damage and consuming all stacks on the primary target. \n\nDeep Breath cannot occur more than once every 6 sec.", cm=1535, q=3, lvl=1, ms=1, f={"Caster DPS", "Melee DPS", "Ranged DPS"}, t=true },
  [201340] = { n="Cyclone of Cold Bones", d="When you cast a spell or ability, you have a chance to unleash a Cyclone of Cold Bones for 6 sec, dealing 30+fire spell powerI*0.4+attack power*0.2 Frost damage every 1 sec to enemies within 8 yards and leaving Coldflame in your wake. Coldflame deals fire spell powerI*0.2+attack power*0.1 Frost damage every 1 sec.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201344] = { n="Deathwhisper’s Barrier", d="When damage would bring you below 50% health, you gain a Mana Barrier for 8 sec, absorbing damage equal to 30% of your maximum mana. \nIf you have no mana, Mana Barrier instead absorbs damage equal to 15% of your maximum health. \n\nWhile active, Mana Barrier deals 1+shadow spell power*0.4+attack power*0.2 Shadow damage every 1 sec to nearby enemies.\n\nThis effect cannot occur more than once every 30 sec.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201348] = { n="Gunship Barrage", d="While in combat, you periodically ready a Cannon Blast. Your next damaging spell or ability calls it down at the target location, dealing 1+fire spell powerI*1+attack power*0.5 Fire damage to all enemies within 8 yards.\n\nStriking 3 or more enemies readies the next blast 4 sec sooner.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201354] = { n="Scent of Blood", d="Damaging an enemy below 35% health grants Scent of Blood for 3 sec, increasing your attack speed and casting speed by 15%.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201356] = { n="Inhaled Blight", d="Every 6 sec while in combat, you inhale the surrounding blight and unleash Pungent Blight, dealing 30+shadow spell power*0.6+attack power*0.3 Shadow damage to all enemies within 12 yards and applying 3 stacks of Mutated Blight. Pungent Blight deals 5% increased damage per stack of Mutated Blight already on the target.\n\nMutated Blight: Deals 3+shadow spell power*0.075+attack power*0.0375 Plague damage every 1 sec for 8 sec. Stacks up to 20 times.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201360] = { n="Slime Spray", d="Your direct damage spells and abilities have a chance to afflict the target with Mutated Infection for 8 sec, dealing 15+nature spell power*0.3+attack power*0.15 Nature damage every 1 sec and applying a stack of Mutated Blight every 2 sec. \n\nWhen Mutated Infection expires or the target dies, it leaves behind Sticky Ooze for 6 sec, dealing 16+nature spell power*0.30+attack power*0.15 Nature damage every 2 sec to all enemies within 8 yards and applying a stack of Mutated Blight every 2 sec. Mutated Infection cannot occur more than once every 6 sec.\n\nMutated Blight: Deals 3+shadow spell power*0.075+attack power*0.0375 Plague damage every 1 sec for 8 sec. Stacks up to 20 times.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201366] = { n="Malleable Goo", d="Your damaging spells and abilities have a chance to hurl Malleable Goo at the target location, dealing 80+nature spell power*2+attack power*1 Nature damage to all enemies within 8 yards and afflicting them with Malleable for 6 sec. Malleable enemies are slowed by 30% and take 10% increased damage from Mutated Blight.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201370] = { n="Shock Vortex", d="When 6 or more enemies are within 10 yards of you, you create a Shock Vortex at your location for 8 sec. The vortex pulls nearby enemies toward its center, dealing 10+nature spell power*0.2+attack power*0.1 Nature damage every 1 sec and slowing them by 50%. \n\nWhen it expires, Shock Vortex erupts, dealing 65+nature spell power*1.6+attack power*0.8 Nature damage to all enemies within it. \n\nShock Vortex cannot occur more than once every 12 sec.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201378] = { n="Dark Nucleus", d="When you take damage, you have a chance to summon a Dark Nucleus for 8 sec. The Dark Nucleus absorbs 20% of the damage you take, up to a maximum of 30% of your maximum health. When it expires or is fully consumed, Dark Nucleus hurls an Empowered Shadow Lance at your target, dealing Shadow damage equal to twice the amount absorbed.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201382] = { n="Conjured Flame", d="Killing a burning enemy conjures a Ball of Flame that seeks out a nearby enemy, leaving Burning Flames in its wake. Burning Flames deal 10+fire spell powerI*0.3+attack power*0.15 Fire damage every 1 sec to nearby enemies for 6 sec. \n\nWhen the Ball of Flame reaches its target, it explodes, dealing 50+fire spell powerI*1.25+attack power*0.625 Fire damage to all enemies within 8 yards. \n\nThis effect cannot occur more than once every 2 sec.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201388] = { n="Blood Mirror", d="Your damaging spells and abilities have a chance to bind your target to the nearest enemy for 8 sec. While bound, 30% of direct damage dealt to either target by you is also dealt to the other as Shadow damage. \n\nIf either target dies while bound, the surviving target is afflicted with Vampiric Bite, increasing damage taken from you by 15% for 6 sec.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201394] = { n="Emerald Vigor", d="Healing an ally below 50% health grants them Emerald Vigor for 8 sec, increasing healing received from you by 15%. \n\nIf an ally with Emerald Vigor is healed above 90% health, Emerald Vigor blooms, healing up to 3 nearby injured allies for 60+\nH*1.75.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201398] = { n="Permeating Chill", d="Your Frost damage has a chance to afflict the target with Permeating Chill for 6 sec, increasing Frost damage taken from you by 10%. \n\nIf an enemy dies while afflicted, it shatters violently, dealing 50+frost spell power*1+attack power*0.5 Frost damage to all enemies within 8 yards.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201402] = { n="Defile", d="Killing an enemy creates Defile at its location for 8 sec, dealing 0+shadow spell power*0.4+attack power*0.2 Shadow damage every 1 sec to enemies within it. \n\nEach enemy slain within Defile increases its radius by 1 yard, damage by 10%, and duration by 1 sec, up to 10 times. \n\nOnly one Defile can be active at a time.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201406] = { n="Necrotic Plague", d="Your damage-over-time effects have a chance to afflict the target with Necrotic Plague for 15 sec, dealing shadow spell power*0.6+attack power*0.3 Plague damage every 1 sec. \n\nIf a target afflicted by Necrotic Plague dies, it jumps to a nearby enemy, refreshing its duration and increasing its damage by 25%, up to 200%.\n\nOnly one Necrotic Plague can be active at a time.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201410] = { n="Frostmourne Hungers", d="While in combat, you periodically mark a nearby enemy with Harvest Soul for 10 sec, prioritizing enemies with the lowest maximum health. \n\nIf the marked enemy dies while afflicted, you devour its soul, granting Harvested Soul for 12 sec. Harvested Soul increases damage done by 2%, stacking up to 10 times. \n\nAt 10 stacks, your damaging spells and abilities also release a burst of Shadowfrost damage around the target, dealing 25+shadow spell power*0.5+attack power*0.25 Shadowfrost damage.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201416] = { n="Blade Tempest", d="Dealing Physical damage to an enemy afflicted by one of your damage-over-time effects has a chance to summon a Warborn Reflection at its location. \n\nThe reflection unleashes Blade Tempest for 8 sec, dealing 30+shadow spell power*0.6+attack power*0.3 Physical damage every 1 sec to nearby enemies.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201420] = { n="Sundered Formation", d="Your Physical damage has a chance to expose the target's armor for 8 sec, increasing Physical damage taken from you by 10%. \n\nIf the exposed target is within 8 yards of at least 2 other enemies, your Physical damage against the target cleaves nearby enemies for 20% of the damage dealt.\n\nOnly one target can be exposed at a time.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201424] = { n="Flame Beacon", d="Your Fire damage has a chance to mark the target with Flame Beacon for 6 sec. While marked, the target releases a Conflagration every 1 sec, dealing 10+fire spell powerI*0.2+attack power*0.1 Fire damage to nearby enemies. \n\nIf the marked target dies, it erupts in a Fire Nova, dealing 50+fire spell powerI*1+attack power*0.5 Fire damage to all enemies within 10 yards.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
  [201428] = { n="Twilight Combustion", d="Your Fire damage has a chance to afflict the target with Fiery Combustion for 8 sec, dealing 5+fire spell powerI*0.1+attack power*0.05 Fire damage every 1 sec. Your Shadow damage has a chance to afflict the target with Soul Consumption for 8 sec, dealing 5+shadow spell power*0.1+attack power*0.05 Shadow damage every 1 sec.\n\nIf both effects are active on the same target, they are consumed to create a Twilight Rift beneath it for 6 sec, dealing 30+shadow spell power*0.6+attack power*0.3 Shadowflame damage every 1 sec to nearby enemies.", cm=1535, q=3, lvl=1, ms=1, f={}, t=true },
}

